.brand-text::after {
	content: '';
	position: absolute;
	bottom: -3px;
	left: 0;
	width: 0;
	height: 2px;
	background: #ef4056;
	border-radius: 2px;
	transition: width 0.35s ease;
}

.site-header.simple-header .welcome-user {
	font-weight: 600;
	color: #ffffff;
	background: linear-gradient(135deg, #ef4056 0%, #d32f4a 100%);
	padding: 7px 18px;
	border-radius: 100px;
	border: none;
	box-shadow: 0 2px 8px rgba(239, 64, 86, 0.3);
	display: inline-flex;
	align-items: center;
	gap: 6px;
	transition: background 0.25s ease, box-shadow 0.25s ease, transform 0.2s ease;
	cursor: default;
}
